class DialogMenu
{
public:
    enum {
        DM_TYPE_MNG,
        DM_TYPE_FMT,
        DM_TYPE_YES,
        DM_TYPE_OK,
        DM_TYPE_PROGRESS,
        DM_TYPE_EMPTY
    };

private:
    enum { DM_YES, DM_NO, DM_OK, DM_FMT, DM_CNL, DM_MNG, DM_CNL2, DM_NUM };
    char data[0x160];
    BoxText* message;
    BoxText* prompt;
    int type;
    char padding[0x1c];
    int draw_count;
    FEMenuEntry* entry[DM_NUM];

public:
    void Draw();
};

void DialogMenu::Draw()
{
	draw_count++;
	if(type == DM_TYPE_YES)
	{
		entry[DM_YES]->Draw();
		entry[DM_NO]->Draw();
	}
	else if(type == DM_TYPE_OK)
	{
		entry[DM_OK]->Draw();
	}
	else if( type == DM_TYPE_FMT )
	{
		entry[DM_FMT]->Draw();
		entry[DM_CNL]->Draw();
	}
	else if( type == DM_TYPE_MNG )
	{
		entry[DM_MNG]->Draw();
		entry[DM_CNL2]->Draw();
	}
	message->Draw();
	prompt->Draw();
}
